struct Stack {
    data: Vec<Char>,
}

fn reverse(s: &mut Stack) {
    for i in 0..(len(s.data) / 2) {
        let l = get(s.data, i)?;
        let r = get(s.data, len(s.data) - i - 1)?;
        s.data[i] = r;
        s.data[len(s.data) - i - 1] = l;
    }
}

